# Result-table-only plotting. Does not read Seurat, counts or pseudobulk objects.
source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');source(file.path(S,'theme.R'));source(file.path(S,'export.R'));suppressPackageStartupMessages(library(ggplot2));jin_setup()
figs<-list();dict<-rd('final_label_dictionary.tsv');cellpal<-setNames(dict$color,dict$celltype);dp<-setNames(c('#377eb8','#e15759','#59a14f','#984ea3','#e6ab02'),sort(unique(rd('sample_metadata.tsv')$dataset)));hp<-c(L50='#4575b4',H50='#fdae61',H10='#f46d43',H05='#d73027');rr<-c('Treg','Tfh/CXCL13-like','Arterial EC','Capillary EC')
export<-function(p,d,stem,w,h,note=''){
 df<-file.path(B,'plot_data',paste0(stem,'.tsv.gz'));fwrite(d,df,sep='\t',na='NA',compress='gzip');custom_theme<-p$theme;p<-p+jin_theme()+custom_theme;files<-jin_export(p,file.path(B,'figures',stem),width=w,height=h);figs[[stem]]<<-data.table(figure_id=stem,file=unname(files),part=names(files),data_file=df,width_in=w,height_in=h,note=note);cat('Rendered',stem,'\n')
}
q<-rd('specimen_exposure_eligibility.tsv');pr<-rd('pseudobulk_profiles.tsv');plan<-rd('model_plan.tsv');types<-c('L50','H50','H10','H05',rr)
v<-merge(CJ(sample_uid=q$sample_uid,profile_type=types),pr[,.(sample_uid,profile_type,n_cells)],all.x=TRUE,by=c('sample_uid','profile_type'));v[is.na(n_cells),n_cells:=0];v<-merge(v,q[,.(sample_uid,specimen_id,dataset,main_patient)],by='sample_uid');v[,specimen_label:=paste0(specimen_id,ifelse(grepl('T4463209',specimen_id),' (same patient)',''))];v[,specimen_label:=factor(specimen_label,levels=rev(unique(v[order(dataset,specimen_id),specimen_label])))];v[,profile_type:=factor(profile_type,levels=types)];v[,log_cells:=log10(1+n_cells)]
p<-ggplot(v,aes(profile_type,specimen_label,fill=log_cells))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=n_cells),size=3)+scale_fill_gradient(low='white',high='#2171b5',name='log10(1 + cells)',guide=guide_colourbar(display='rectangles'))+labs(x='Original cells (main pseudobulk: n >= 50; sensitivity: n >= 30)',y=NULL)+scale_x_discrete(labels=function(x)gsub('/','/\n',x));export(p,v,'coverage_all_specimens',13,15,'Original cells; a/b same patient. Zero denotes no captured cells of that subtype, not zero expression.')
e<-rd('candidate_expression_detection.tsv.gz');e<-e[status=='computed'];for(g in c('NECTIN2','PVR','VEGFA','VEGFB','VEGFC','PGF','MDK','MIF','LGALS9')){
 vv<-list();for(h in c('H50','H10','H05')){ss<-pr[main_patient & n_cells>=50 & profile_type%in%c('L50',h),.N,by=sample_uid][N==2,sample_uid];z<-e[gene==g&sample_uid%in%ss&profile_type%in%c('L50',h)];z[,high_definition:=paste0(h,' vs L50\n(n = ',length(ss),' recorded units)')];z[,state:=ifelse(profile_type=='L50','L50','High')];vv[[h]]<-z};v<-rbindlist(vv);v[,state:=factor(state,levels=c('L50','High'))];v[,high_definition:=factor(high_definition,levels=unique(high_definition))]
 p<-ggplot(v,aes(state,log1p(normalized_mean),group=sample_uid,colour=dataset))+geom_line(linewidth=.4,alpha=.6)+geom_point(size=1.5)+facet_wrap(~high_definition,nrow=1)+scale_colour_manual(values=dp,name='Dataset')+labs(x=NULL,y=paste0(g,' mean RNA expression (log1p)'));export(p,v,paste0('epi_paired_',g),12,4.7,'Main-a, n >= 50 in both Epi states; lines are paired specimens. Descriptive expression, not cellular P values.')
}
for(r in rr){genes<-if(r%in%rr[1:2])c('NECTIN2','TIGIT','PVRIG','CD226','PVR')else c('FLT1','KDR','FLT4','NRP1','NRP2','TEK');v<-e[profile_type==r&main_patient&gene%in%genes&n_cells>=30];if(!nrow(v))next;v[,specimen_label:=paste0(specimen_id,' (n=',n_cells,')')];v[,gene:=factor(gene,levels=genes)];p<-ggplot(v,aes(gene,specimen_label,size=positive_fraction,colour=log1p(normalized_mean)))+geom_point()+scale_size_continuous(range=c(.3,5),limits=c(0,1),name='Positive cell fraction')+scale_colour_gradient(low='#deebf7',high='#08519c',name='log1p(mean RNA)',guide=guide_colourbar(display='rectangles'))+labs(x=paste0(r,' (',uniqueN(v$patient_uid_recorded),' recorded units; n >= 30)'),y=NULL);export(p,v,paste0('receptor_detection_',gsub('[^A-Za-z0-9]','_',r)),10,max(5,uniqueN(v$sample_uid)*.3+1.7),'Main-a descriptive profiles; exact zero expression retained; profiles below 30 are excluded and recorded in coverage table.')}
# Exposure distribution retains dataset variation; a/b labeled rather than treated as independent inference.
v<-melt(q,id.vars=c('sample_uid','specimen_id','dataset','main_patient'),measure.vars=c('Q50','Q95'),variable.name='exposure',value.name='score');p<-ggplot(v,aes(dataset,score,colour=dataset))+geom_boxplot(outlier.shape=NA,linewidth=.4,show.legend=FALSE)+geom_point(position=position_jitter(width=.15,seed=123),size=1.8,show.legend=FALSE)+geom_text(data=v[grepl('T4463209a',specimen_id)],aes(label=specimen_id),position=position_nudge(x=.28),size=3,hjust=-.05,show.legend=FALSE)+geom_text(data=v[grepl('T4463209b',specimen_id)],aes(label=specimen_id),position=position_nudge(x=-.28),size=3,hjust=-.05,show.legend=FALSE)+facet_wrap(~exposure)+coord_flip()+scale_colour_manual(values=dp)+labs(x='Dataset (40 descriptive specimens; a/b share one patient)',y='MP10 score');export(p,v,'exposure_by_dataset',12,5,'Model exposure standardized by original 39 main-a specimen SD; original-scale scores shown.')
ac<-rd('activity_associations.tsv.gz');main<-plan[primary==TRUE];covn<-pr[main_patient&n_cells>=50&profile_type%in%rr,.(n_units=uniqueN(patient_uid_recorded)),by=profile_type]
for(resource in c('PROGENy','CollecTRI','DoRothEA_AB')){
 resid<-resource
 z<-merge(ac[resource==resid&mask=='Full'&model_id%in%main[kind=='receiver',model_id]],main[,.(model_id,target)],by='model_id')
 genes<-if(resource=='PROGENy')sort(unique(ac[resource=='PROGENy',source]))else unique(z[order(sample_model_q),head(.SD,5),by=target]$source)
 v<-merge(CJ(source=genes,target=rr),z,by=c('source','target'),all.x=TRUE);v<-merge(v,covn,by.x='target',by.y='profile_type',all.x=TRUE);v[,target_label:=paste0(target,'\n(n = ',n_units,')')];v[,label:=ifelse(is.na(activity_effect),'NE',ifelse(sample_model_q<.05,'*',''))];lim<-max(abs(v$activity_effect),na.rm=TRUE);if(!is.finite(lim)||lim==0)lim<-1
 p<-ggplot(v,aes(target_label,source,fill=activity_effect))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=4)+scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-lim,lim),na.value='#d9d9d9',name='ULM score change / MP10 SD',guide=guide_colourbar(display='rectangles'))+labs(x='MP10 median model: * sample-model BH q < 0.05; NE = not evaluable',y=NULL);export(p,v,paste0('receiver_',resource),12,max(6,length(genes)*.28+1.5),'Each receiver has its own eligible main-a specimens; dataset-adjusted limma activity models. ULM internal P is not used here.')
}
v<-merge(ac[resource=='PROGENy'&model_id%in%main[kind=='Epi',model_id]],main[,.(model_id,target)],by='model_id');v[,column:=factor(paste(target,mask,sep='\n'),levels=as.vector(t(outer(c('H50','H10','H05'),c('Full','M20-masked'),paste,sep='\n'))))];v[,label:=ifelse(sample_model_q<.05,'*','')];lim<-max(abs(v$activity_effect));p<-ggplot(v,aes(column,source,fill=activity_effect))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=4)+scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-lim,lim),name='Paired activity effect',guide=guide_colourbar(display='rectangles'))+labs(x='High vs L50 (n = 39 / 33 / 24 recorded units); * sample-model BH q < 0.05',y=NULL);export(p,v,'epi_PROGENy_Full_M20',12,7,'Full and M20-masked remove scoring genes only downstream; no counts, library size or group changes.')
if(file.exists(tb('gsea_results.tsv.gz'))){g<-rd('gsea_results.tsv.gz');z<-merge(g[library=='Hallmark'&mask=='Full'&model_id%in%main[kind=='receiver',model_id]],main[,.(model_id,target)],by='model_id');v<-merge(CJ(pathway=sort(unique(g[library=='Hallmark',pathway])),target=rr),z,by=c('pathway','target'),all.x=TRUE);v[,label:=ifelse(is.na(NES),'NE',ifelse(padj<.05,'*',''))];v[,pathway_label:=gsub('_',' ',sub('HALLMARK_','',pathway))];v<-merge(v,covn,by.x='target',by.y='profile_type',all.x=TRUE);v[,target_label:=paste0(target,'\n(n=',n_units,')')];p<-ggplot(v,aes(target_label,pathway_label,fill=NES))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=3)+scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-3,3),oob=scales::squish,na.value='#d9d9d9',name='NES',guide=guide_colourbar(display='rectangles'))+labs(x='MP10 median; * Hallmark BH q < 0.05; NE = not evaluable',y=NULL);export(p,v,'receiver_Hallmark',12,16,'All 50 Hallmarks, both directions; gene-level signed QL statistics. Same NES scale for all receivers.')}
if(file.exists(tb('candidate_de_effects.tsv'))){v<-rd('candidate_de_effects.tsv')[primary==TRUE&kind=='Epi'];v[,label:=ifelse(is.na(logFC),'NE',ifelse(FDR<.05,'*',''))];v[,target:=factor(paste0(target,' (n=',n_specimens,')'),levels=c('H50 (n=39)','H10 (n=33)','H05 (n=24)'))];p<-ggplot(v,aes(target,gene,fill=logFC))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=4)+scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-1,1),oob=scales::squish,na.value='#d9d9d9',name='edgeR log2 FC\n(colors capped at +/-1)',guide=guide_colourbar(display='rectangles'))+labs(x='High vs L50; * within-comparison BH FDR < 0.05',y=NULL);export(p,v,'epi_ligand_effects',8,8)}
if(file.exists(tb('nichenet_ligand_activities.tsv.gz'))){nn<-rd('nichenet_ligand_activities.tsv.gz');for(id in intersect(main$model_id,nn$model_id)){v<-nn[model_id==id & detection_threshold==.1 & target_direction=='positive' & mask==if(main[model_id==id,kind]=='Epi')'M20-masked'else'Full'];if(!nrow(v))next;v<-v[rank_sender_agnostic<=15 | test_ligand%in%c('NECTIN2','PVR','VEGFA')];v[,test_ligand:=reorder(test_ligand,aupr_corrected)];p<-ggplot(v,aes(aupr_corrected,test_ligand,fill=!is.na(rank_focused)))+geom_col(width=.75)+scale_fill_manual(values=c('TRUE'='#4c78a8','FALSE'='#c7c7c7'),name='Sender detected')+labs(x=paste0('NicheNet corrected AUPR (',v$direction[1],'; ',main[model_id==id,target],')'),y=NULL);export(p,v,paste0('nichenet_activity_',id),10,7,'Activity is a ranking, not a patient-level P/FDR. Positive receiver targets; detection 10%; masked reverse direction.') }}
man<-rbindlist(figs,fill=TRUE);fwrite(man,file.path(B,'config/figure_manifest.tsv'),sep='\t');write_json(list(font='Arial',font_pt=12,dpi=300,line_mm=.4,dataset_colors=as.list(dp),high_colors=as.list(hp),cell_colors=as.list(cellpal),DE_logFC_scale=c(-1,1),GSEA_NES_scale=c(-3,3),NE_color='#d9d9d9'),file.path(B,'config/plot_config.json'),pretty=TRUE,auto_unbox=TRUE)
cat('REPLOT COMPLETE\n')
